// Self-contained: every local import is inlined below. Requires only d3, motion, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import * as d3 from 'd3';
import { useEffect, useMemo, useState } from 'react';
import { motion } from 'motion/react';

// ---- inlined from unionfind ----
/**
 * A scripted union-find run: naive unions (root attached under root, no rank) grow tall
 * chains on purpose, then finds with path compression flatten them. One frame per
 * operation, laid out with d3.tree over the whole forest per frame — the chart tweens node
 * positions between frames rather than re-laying-out per animation tick.
 */


const UF_N = 20;

interface UfFrame {
  /** The operation, e.g. "union(0, 8)" or "find(0) compresses". */
  label: string;
  /** The depth argument, e.g. "depth 8 → 1". */
  note: string;
  /** Nodes to pick out: the re-parented root for a union, the walked path for a find. */
  highlight: number[];
  /** Parent per node after this operation; a root is its own parent. */
  parents: number[];
  /** Layout position per node, x in [0,1], y = depth / global max depth. */
  positions: [number, number][];
}

interface TreeDatum {
  id: number;
  children: TreeDatum[];
}

/** Tidy-tree the forest under a virtual root; returns x and true depth per node. */
function layout(parents: number[]): { xs: number[]; depths: number[] } {
  const byId: TreeDatum[] = Array.from({ length: UF_N }, (_, id) => ({ id, children: [] }));
  const virtualRoot: TreeDatum = { id: -1, children: [] };
  parents.forEach((p, i) => (p === i ? virtualRoot : byId[p]).children.push(byId[i]));

  const root = d3.tree<TreeDatum>().size([1, 1])(d3.hierarchy(virtualRoot));
  const xs = new Array<number>(UF_N).fill(0);
  const depths = new Array<number>(UF_N).fill(0);
  for (const node of root.descendants()) {
    if (node.data.id < 0) continue;
    xs[node.data.id] = node.x;
    depths[node.data.id] = node.depth - 1;
  }
  return { xs, depths };
}

const ufFrames: UfFrame[] = (() => {
  const parents = Array.from({ length: UF_N }, (_, i) => i);
  const findRoot = (i: number) => {
    while (parents[i] !== i) i = parents[i];
    return i;
  };
  const depth = (i: number) => {
    let d = 0;
    while (parents[i] !== i) {
      i = parents[i];
      ++d;
    }
    return d;
  };
  const maxDepth = () => Math.max(...parents.map((_, i) => depth(i)));

  const raw: Omit<UfFrame, 'positions'>[] = [];
  const layouts: { xs: number[]; depths: number[] }[] = [];
  const record = (label: string, note: string, highlight: number[]) => {
    raw.push({ label, note, highlight, parents: [...parents] });
    layouts.push(layout(parents));
  };

  record('20 singletons', 'max depth 0', []);

  const union = (a: number, b: number) => {
    const rootA = findRoot(a);
    parents[rootA] = findRoot(b);
    record(`union(${a}, ${b})`, `max depth ${maxDepth()}`, [rootA]);
  };
  const chain = (lo: number, hi: number) => {
    for (let i = lo; i < hi; ++i) union(i, i + 1);
  };

  const find = (i: number) => {
    const before = depth(i);
    const root = findRoot(i);
    const path: number[] = [];
    for (let j = i; j !== root; j = parents[j]) path.push(j);
    record(`find(${i})`, `walks depth ${before}`, [...path, root]);
    if (before <= 1) {
      raw[raw.length - 1].note = `depth ${before} — already flat`;
      return;
    }
    for (const j of path) parents[j] = root;
    record(`find(${i}) compresses`, `depth ${before} → 1`, [...path, root]);
  };

  chain(0, 7); // a chain 0 → 1 → … → 7, eight nodes deepening one union at a time
  chain(8, 12);
  chain(13, 16);
  chain(17, 19);
  union(0, 8); // hangs the long chain under the medium one: depth(0) is now 8
  find(0); // one find flattens all eight onto the root
  union(13, 17);
  union(13, 0);
  find(13);
  find(5); // amortization: the earlier compression already paid for this one

  const deepest = Math.max(...layouts.flatMap(({ depths }) => depths));
  return raw.map((frame, f) => ({
    ...frame,
    positions: frame.parents.map((_, i): [number, number] => [
      layouts[f].xs[i],
      layouts[f].depths[i] / deepest
    ])
  }));
})();

const FRAME_MS = 700;
const HOLD_FRAMES = 6;
const LAST = ufFrames.length - 1;
const TWEEN = { duration: 0.48, ease: 'easeInOut' } as const;
const HOT = '#e0538a';
const PAD = 14;

export default function UnionFind({ width }: { width: number }) {
  const safeWidth = Math.max(1, width);
  const treeHeight = Math.round(safeWidth * 0.5);
  const height = treeHeight + 2 * PAD + 20;
  const innerWidth = Math.max(1, safeWidth - 2 * PAD);
  const radius = Math.max(3, safeWidth * 0.011);

  // The SSR frame is the fully flattened forest; the effect rewinds and replays the script.
  const [step, setStep] = useState(LAST);

  useEffect(() => {
    const end = LAST + HOLD_FRAMES;
    setStep(0);
    const id = window.setInterval(() => setStep((s) => (s >= end ? 0 : s + 1)), FRAME_MS);
    return () => window.clearInterval(id);
  }, []);

  const frame = ufFrames[Math.min(step, LAST)];

  const nodes = useMemo(() => {
    const hot = new Set(frame.highlight);
    const rootOf = (i: number): number => (frame.parents[i] === i ? i : rootOf(frame.parents[i]));
    return frame.positions.map(([fx, fy], i) => ({
      id: i,
      x: PAD + fx * innerWidth,
      y: PAD + fy * treeHeight,
      parent: frame.parents[i],
      isRoot: frame.parents[i] === i,
      hot: hot.has(i),
      color: d3.schemeObservable10[rootOf(i) % 10]
    }));
  }, [frame, innerWidth, treeHeight]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Union-find under naive unions and path-compressing finds: unions chain the forest into tall trees, then a single find drags every node on its walk directly under the root, and the tree's height visibly collapses — amortized analysis made physical"
    >
      {nodes.map(
        (node) =>
          !node.isRoot && (
            <motion.line
              key={`edge-${node.id}`}
              initial={false}
              animate={{
                x1: node.x,
                y1: node.y,
                x2: nodes[node.parent].x,
                y2: nodes[node.parent].y
              }}
              transition={TWEEN}
              stroke={node.hot ? HOT : 'var(--line)'}
              strokeWidth={node.hot ? 2 : 1.2}
            />
          )
      )}
      {nodes.map((node) => (
        <motion.g
          key={node.id}
          initial={false}
          animate={{ x: node.x, y: node.y }}
          transition={TWEEN}
        >
          <circle
            r={node.isRoot ? radius * 1.35 : radius}
            fill={node.hot ? HOT : node.color}
            stroke={node.isRoot ? 'var(--text)' : 'none'}
            strokeWidth={node.isRoot ? 1.6 : 0}
          />
          {radius >= 6 && (
            <text y={3.5} textAnchor="middle" fontSize={radius} fill="var(--bg)" fontWeight={600}>
              {node.id}
            </text>
          )}
        </motion.g>
      ))}
      <text x={4} y={height - 6} fill="var(--text)" fontSize={11} fontWeight={600}>
        {frame.label}
      </text>
      <text x={width - 4} y={height - 6} textAnchor="end" fill="var(--muted)" fontSize={11}>
        {frame.note}
      </text>
    </svg>
  );
}
